import React from 'react';
import { i18n } from '../../services/i18n.js';
import { storageService } from '../../services/storage.js';

export function PaywallModal({ onClose, onTierChanged }) {
  const isPremium = storageService.settings.isPremium;

  const handleToggleTier = () => {
    const nextStatus = !isPremium;
    storageService.saveSettings({ isPremium: nextStatus });
    if (onTierChanged) onTierChanged(nextStatus);
    onClose();
  };

  return (
    <div class="m3-modal-backdrop" onClick={onClose}>
      <div class="m3-modal-card" style={{ maxWidth: '520px' }} onClick={(e) => e.stopPropagation()}>
        <div class="modal-header">
          <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
            <span class="material-symbols-rounded" style={{ fontSize: '28px', color: '#FFA000' }}>workspace_premium</span>
            <h2 class="modal-title">{i18n.t('paywall_title')}</h2>
          </div>
          <button class="m3-action-btn" onClick={onClose}>
            <span class="material-symbols-rounded">close</span>
          </button>
        </div>

        <div class="modal-body">
          <p style={{ fontSize: '0.95rem', color: 'var(--m3-text-secondary)', lineHeight: '1.5' }}>
            {i18n.t('paywall_desc')}
          </p>

          <div class="paywall-features-list">
            {[
              i18n.t('feature_lists'),
              i18n.t('feature_tasks'),
              i18n.t('feature_subtasks'),
              i18n.t('feature_habits'),
              i18n.t('feature_reminders'),
              i18n.t('feature_advanced_stats'),
              i18n.t('feature_data_export')
            ].map((f, idx) => (
              <div key={idx} class="paywall-feature-item">
                <span class="material-symbols-rounded" style={{ color: 'var(--m3-primary)', fontSize: '20px' }}>
                  check_circle
                </span>
                <span>{f}</span>
              </div>
            ))}
          </div>

          <div style={{ background: 'var(--m3-surface-container)', padding: '1rem', borderRadius: '16px', display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginTop: '0.5rem' }}>
            <div>
              <div style={{ fontSize: '0.95rem', fontWeight: '800' }}>
                {isPremium ? i18n.t('premium_tier') : i18n.t('free_tier')}
              </div>
              <div style={{ fontSize: '0.8rem', color: 'var(--m3-text-muted)', marginTop: '0.1rem' }}>
                {isPremium ? 'جميع الميزات مفعلة' : 'محدودية في عدد القوائم والعادات'}
              </div>
            </div>

            <button class="m3-btn-primary" onClick={handleToggleTier}>
              {isPremium ? (i18n.isRTL() ? 'الخطة المميزة مفعلة ✅' : 'Premium Active ✅') : (i18n.isRTL() ? 'تفعيل الخطة المميزة 🚀' : 'Upgrade to Premium 🚀')}
            </button>
          </div>
        </div>

        <div class="modal-actions-row">
          <button class="m3-btn-secondary" onClick={onClose}>
            {i18n.t('close')}
          </button>
        </div>
      </div>
    </div>
  );
}
